const raw = $json;

// 혹시 데이터가 body 안에 들어오는 경우까지 대응
const data = raw.body || raw;

// 필수값 확인
if (!data.article_id) {
  throw new Error(
    `article_id가 없습니다. 현재 입력값: ${JSON.stringify(data)}`
  );
}

if (!data.title) {
  throw new Error(
    `기사 title이 없습니다. 현재 입력값: ${JSON.stringify(data)}`
  );
}

if (!data.content) {
  throw new Error(
    `기사 content가 없습니다. 현재 입력값: ${JSON.stringify(data)}`
  );
}

// 키워드 처리
const selectedKeywords =
  Array.isArray(data.selected_keywords)
    ? data.selected_keywords
    : [];

// Instagram 전용 Workflow이므로
// platform은 여기서 고정
return [
  {
    json: {
      article_id: data.article_id,
      title: data.title,
      content: data.content,

      selected_keywords: selectedKeywords,

      requirements: data.requirements || '',

      platform: 'instagram'
    }
  }
];

const draft = $('Parse Draft').item.json;
const factCheck = $('Parse Validator 1').item.json;
const requirementCheck = $('Parse Validator 2').item.json;

const overallPass =
  factCheck.pass === true &&
  requirementCheck.pass === true;

return [
  {
    json: {
      article_id: draft.article_id,

      platform: 'instagram',

      status: overallPass
        ? 'ready_for_user_review'
        : 'needs_review',

      output: {
        core_text: draft.core_text || {
          headline: '',
          summary: '',
          source_evidence: []
        },

        recommended_card_count:
          draft.recommended_card_count || 0,

        card_count_reason:
          draft.card_count_reason || '',

        cards: Array.isArray(draft.cards)
          ? draft.cards
          : []
      },

      validation: {
        fact_check: factCheck,

        requirement_check: requirementCheck,

        summary: {
          overall_pass: overallPass,

          unsupported_claims:
            factCheck.unsupported_claims?.length || 0,

          number_mismatches:
            factCheck.number_mismatches?.length || 0,

          quote_mismatches:
            factCheck.quote_mismatches?.length || 0,

          evidence_mismatches:
            factCheck.evidence_mismatches?.length || 0,

          missing_keywords:
            requirementCheck.missing_keywords?.length || 0,

          requirement_omissions:
            requirementCheck.requirement_omissions?.length || 0,

          platform_rule_violations:
            requirementCheck.platform_rule_violations?.length || 0
        }
      },

      ui_state: {
        editable: true,
        evidence_visible: true,

        photo_search_available: true,
        photo_auto_insert: false,

        black_card_default: true,

        ready_for_render: overallPass
      }
    }
  }
];
